export interface ConnectorConfig {
  /** Shopify shared secret for HMAC-SHA256 verification (from SHOPIFY_SHARED_SECRET). */
  shopifySharedSecret: string;
  /** Slack bot token with chat:write scope (from SLACK_BOT_TOKEN). */
  slackBotToken: string;
  /** Target Slack channel ID (e.g., C12345) or name (e.g., #general). */
  slackChannel: string;
  /** Injected fetch for testing; defaults to global fetch. */
  fetch?: typeof fetch;
  /** Optional raw request body for HMAC verification. If provided with shopifySignature, verification runs. */
  rawBody?: string;
  /** Optional X-Shopify-Hmac-Sha256 header value for HMAC verification. */
  shopifySignature?: string;
}

export interface ShopifyOrderPayload {
  id: number;
  name: string;
  email: string;
  total_price: string;
  line_items: Array<{ name: string; quantity: number }>;
}

export interface SlackMessageResult {
  ok: boolean;
  channel: string;
  ts: string;
}

const SLACK_API_URL = 'https://slack.com/api/chat.postMessage';

async function verifyHmac(
  secret: string,
  rawBody: string,
  signature: string,
): Promise<void> {
  const encoder = new TextEncoder();
  const keyData = encoder.encode(secret);
  const messageData = encoder.encode(rawBody);
  const cryptoKey = await crypto.subtle.importKey(
    'raw',
    keyData,
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['sign'],
  );
  const signatureBytes = await crypto.subtle.sign('HMAC', cryptoKey, messageData);
  const expectedSignature = Array.from(new Uint8Array(signatureBytes))
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');
  const providedSignature = signature.replace(/^sha256=/, '');
  if (expectedSignature !== providedSignature) {
    throw new Error('Invalid Shopify HMAC signature');
  }
}

function formatSlackMessage(payload: ShopifyOrderPayload): string {
  const itemsSummary = payload.line_items
    .map((item) => `${item.quantity} x ${item.name}`)
    .join(', ');
  return `New order ${payload.name} from ${payload.email} for $${payload.total_price}: ${itemsSummary}`;
}

function validatePayload(payload: unknown): asserts payload is ShopifyOrderPayload {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Payload must be an object');
  }
  const p = payload as Record<string, unknown>;
  const requiredFields: Array<keyof ShopifyOrderPayload> = ['id', 'name', 'email', 'total_price', 'line_items'];
  for (const field of requiredFields) {
    if (!(field in p)) {
      throw new Error(`Missing required field: ${field}`);
    }
  }
  if (!Array.isArray(p.line_items)) {
    throw new Error('line_items must be an array');
  }
  for (const [i, item] of p.line_items.entries()) {
    if (!item || typeof item !== 'object') {
      throw new Error(`line_items[${i}] must be an object`);
    }
    const li = item as Record<string, unknown>;
    if (typeof li.name !== 'string' || typeof li.quantity !== 'number') {
      throw new Error(`line_items[${i}] must have string name and number quantity`);
    }
  }
}

export async function handle(
  payload: ShopifyOrderPayload,
  config: ConnectorConfig,
): Promise<SlackMessageResult> {
  validatePayload(payload);

  if (config.rawBody !== undefined && config.shopifySignature !== undefined) {
    await verifyHmac(config.shopifySharedSecret, config.rawBody, config.shopifySignature);
  }

  const text = formatSlackMessage(payload);
  const body = JSON.stringify({ channel: config.slackChannel, text });

  const fetchImpl = config.fetch ?? fetch;
  const response = await fetchImpl(SLACK_API_URL, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.slackBotToken}`,
      'Content-Type': 'application/json',
    },
    body,
  });

  if (!response.ok) {
    throw new Error(`Slack API error: ${response.status} ${response.statusText} for POST ${SLACK_API_URL}`);
  }

  const result = (await response.json()) as SlackMessageResult;
  if (!result.ok) {
    throw new Error(`Slack API returned ok=false: ${JSON.stringify(result)}`);
  }
  return result;
}

