    const { fetch, calls: recordedCalls } = fakeFetch((req) => {
      if (req.url === 'https://slack.com/api/chat.postMessage' && req.method === 'POST') {
        return jsonResponse({ ok: true, channel: 'C12345', ts: '1234567890.123456' });
      }
      return jsonResponse({ error: 'not found' }, 404);
    });
    calls = recordedCalls;
    baseConfig = {
      shopifySharedSecret: 'test-secret',
      slackBotToken: 'xoxb-test-token',
      slackChannel: 'C12345',
      fetch,
    };
  });

  it('posts formatted message to Slack with correct payload', async () => {
    const payload: ShopifyOrderPayload = {
      id: 1234567890,
      name: '#1001',
      email: 'customer@example.com',
      total_price: '129.99',
      line_items: [
        { name: 'T-Shirt', quantity: 2 },
        { name: 'Mug', quantity: 1 },
      ],
    };
    const result = await handle(payload, baseConfig);
    expect(result.ok).toBe(true);
    expect(calls.length).toBe(1);
    const call = calls[0];
    expect(call.method).toBe('POST');
    expect(call.url).toBe('https://slack.com/api/chat.postMessage');
    expect(call.json).toEqual({
      channel: 'C12345',
      text: 'New order #1001 from customer@example.com for $129.99: 2 x T-Shirt, 1 x Mug',
    });
    expect(call.headers.get('authorization')).toBe('Bearer xoxb-test-token');
    expect(call.headers.get('content-type')).toBe('application/json');
  });

  it('uses Bearer token authentication', async () => {
    const payload: ShopifyOrderPayload = {
      id: 1,
      name: '#1',
      email: 'a@b.com',
      total_price: '1.00',
      line_items: [{ name: 'Item', quantity: 1 }],
    };
    await handle(payload, baseConfig);
    expect(calls[0].headers.get('authorization')).toBe('Bearer xoxb-test-token');
  });

  it('maps all fields into Slack text message', async () => {
    const payload: ShopifyOrderPayload = {
      id: 999,
      name: '#500',
      email: 'buyer@shop.com',
      total_price: '42.50',
      line_items: [
        { name: 'Widget', quantity: 3 },
        { name: 'Gadget', quantity: 1 },
      ],
    };
    await handle(payload, baseConfig);
    expect(calls[0].json).toEqual({
      channel: 'C12345',
      text: 'New order #500 from buyer@shop.com for $42.50: 3 x Widget, 1 x Gadget',
    });
  });

