    const incompletePayload = {
      id: 1,
      name: '#1',
      email: 'a@b.com',
      total_price: '1.00',
    } as unknown as ShopifyOrderPayload;
    await expect(handle(incompletePayload, baseConfig)).rejects.toThrow('Missing required field: line_items');
  });

