    const { fetch, calls: errorCalls } = fakeFetch(() => jsonResponse({ error: 'rate_limited' }, 429));
    const config = { ...baseConfig, fetch };
    const payload: ShopifyOrderPayload = {
      id: 1,
      name: '#1',
      email: 'a@b.com',
      total_price: '1.00',
      line_items: [{ name: 'Item', quantity: 1 }],
    };
    await expect(handle(payload, config)).rejects.toThrow('Slack API error: 429 Too Many Requests for POST https://slack.com/api/chat.postMessage');
    expect(errorCalls.length).toBe(1);
  });

  it('verifies HMAC when rawBody and signature provided', async () => {
    const { fetch, calls: hmacCalls } = fakeFetch((req) => {
