        return jsonResponse({ ok: true, channel: 'C12345', ts: '1234567890.123456' });
      }
      return jsonResponse({ error: 'not found' }, 404);
    });
    const config: ConnectorConfig = {
      ...baseConfig,
      fetch,
      rawBody: JSON.stringify(SOURCE_EXAMPLE),
      shopifySignature: 'sha256=invalid', // Will fail verification
