    const config: ConnectorConfig = {
      ...baseConfig,
      rawBody: JSON.stringify(SOURCE_EXAMPLE),
      // shopifySignature omitted
    };
    const result = await handle(SOURCE_EXAMPLE as unknown as ShopifyOrderPayload, config);
    expect(result.ok).toBe(true);
    expect(calls.length).toBe(1);
  });
});

